mapper.select:
select o.order_id, o.order_no, o.buyer_name, o.amount, o.paid_amount, o.region, o.phone, o.logistics, o.factory, o.order_date, o.order_status, o.create_time, o.remark, (select group_concat(p.product_name separator ',') from ops_order_item oi left join ops_product p on oi.product_id = p.product_id where oi.order_id = o.order_id) as product_name from ops_order o
AND o.order_no like concat('%', #{orderNo}, '%')
AND o.buyer_name like concat('%', #{buyerName}, '%')
AND o.order_status = #{orderStatus}
AND exists (select 1 from ops_order_item oi2 left join ops_product p2 on oi2.product_id = p2.product_id where oi2.order_id = o.order_id and p2.product_name like concat('%', #{productName}, '%'))
AND o.order_date >= #{orderDateBegin}
AND o.order_date <= #{orderDateEnd}
order by o.create_time desc

mapper.insert:
insert into ops_order( order_no, buyer_name, amount, paid_amount, region, phone, logistics, factory, order_date, order_status, remark, create_time )values( #{orderNo}, #{buyerName}, #{amount}, #{paidAmount}, #{region}, #{phone}, #{logistics}, #{factory}, #{orderDate}, #{orderStatus}, #{remark},
#{createTime} sysdate()
)
